macro_rules! smoke {
    ($name:ident, $ty:ty, $new:path, $trait:ident, $threshold:literal, $route:ident) => {
        #[kani::proof_for_contract(<$ty as $trait>::small_sort)]
        #[kani::unwind(34)]
        fn $name() {
            let input: [u8; 3] = kani::any();
            let n: usize = kani::any();
            kani::assume(n <= 3);
            let mut backing = [$new(0xa5), $new(input[0]), $new(input[1]),
                $new(input[2]), $new(0x5a)];
            kani::assert(enabled::<$ty, KeyLess<$ty>>(), concat!(stringify!($name), "::model_enabled"));
            kani::assert(<$ty as $trait>::small_sort_threshold() == $threshold, concat!(stringify!($name), "::s1_exact_trait_threshold"));
            kani::assert(size_of::<$ty>() == 1 && size_of::<KeyLess<$ty>>() == 0, concat!(stringify!($name), "::type_layout"));
            let left = snapshot::<$ty, KeyLess<$ty>>(&backing[..1]);
            let right = snapshot::<$ty, KeyLess<$ty>>(&backing[n + 1..n + 2]);
            let before = snapshot::<$ty, KeyLess<$ty>>(&backing[1..n + 1]);
            let mut less = KeyLess::<$ty>::new();
            invoke!($route, $ty, $trait, &mut backing[1..n + 1], n, &mut less);
            kani::assert(post::<$ty, KeyLess<$ty>>(before, &backing[1..n + 1]), concat!(stringify!($name), "::post_independent_caller"));
            kani::assert(post::<$ty, KeyLess<$ty>>(left, &backing[..1]), concat!(stringify!($name), "::left_canary"));
            kani::assert(post::<$ty, KeyLess<$ty>>(right, &backing[n + 1..n + 2]), concat!(stringify!($name), "::right_canary"));
            if n == 1 {
                let expected = [$new(input[0])];
                kani::assert(post::<$ty, KeyLess<$ty>>(
                    snapshot::<$ty, KeyLess<$ty>>(&expected), &backing[1..2]), concat!(stringify!($name), "::n1_value_unchanged"));
            }
            if n == 0 {
                kani::assert(post::<$ty, KeyLess<$ty>>(before, &[]), concat!(stringify!($name), "::n0_empty_unchanged"));
            }
            kani::cover(n == 0, "S1_entry_N0_return");
            kani::cover(n == 1, "S1_entry_N1_return");

}

